    ptr = 0
    N = int(input[ptr])
    ptr += 1
    A = list(map(int, input[ptr:ptr+N]))
    ptr += N

    prefix_sleep = [0] * N
    for i in range(1, N):
        if i % 2 == 0:
            prefix_sleep[i] = prefix_sleep[i-1] + (A[i] - A[i-1])
        else:
            prefix_sleep[i] = prefix_sleep[i-1]

    Q = int(input[ptr])
    ptr += 1

    for _ in range(Q):
        l = int(input[ptr])
        r = int(input[ptr+1])
        ptr += 2

        # Calculate total for r
        j_r = bisect.bisect_right(A, r) - 1
        if j_r < 0:
            total_r = 0
        else:
            if j_r % 2 == 0:
                total_r = prefix_sleep[j_r]
            else:
                total_r = prefix_sleep[j_r] + (r - A[j_r])

        # Calculate total for l
        j_l = bisect.bisect_right(A, l) - 1
        if j_l < 0:
            total_l = 0
        else:
            if j_l % 2 == 0:
                total_l = prefix_sleep[j_l]
            else:
                total_l = prefix_sleep[j_l] + (l - A[j_l])

