    N = int(sys.stdin.readline())
    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    size = [0] * (N + 1)
    stack = [(1, -1, False)]

    while stack:
        u, parent, visited = stack.pop()
        if not visited:
            stack.append((u, parent, True))
            for v in adj[u]:
                if v != parent:
                    stack.append((v, u, False))
        else:
            size[u] = 1
            for v in adj[u]:
                if v != parent:
                    size[u] += size[v]

    children_of_1 = adj[1]
    sum_sizes = sum(size[v] for v in children_of_1)
    max_size = max(size[v] for v in children_of_1)
