import math
import sys

class Line:
    def __init__(self, m, b):
        self.m = m
        self.b = b

    def get(self, x):
        return self.m * x + self.b

class LiChaoNode:
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.left = None
        self.right = None
        self.line = None

class LiChaoTree:
    def __init__(self, x_left, x_right):
        self.root = LiChaoNode(x_left, x_right)

    def insert(self, node, new_line):
        l = node.l
        r = node.r
        if node.line is None:
            node.line = new_line
            return
        # Compare at mid
        mid = (l + r) // 2
        current_val = node.line.get(mid)
        new_val = new_line.get(mid)
        if new_val < current_val:
            node.line, new_line = new_line, node.line
        # Decide which child to go to
        if new_line.get(l) < new_line.get(r):
            if l == r:
                return
            if new_line.get(l) < node.line.get(l):
                if not node.left:
                    node.left = LiChaoNode(l, mid)
                self.insert(node.left, new_line)
            else:
                if not node.right:
                    node.right = LiChaoNode(mid + 1, r)
                self.insert(node.right, new_line)
        else:
            if l == r:
                return
            if new_line.get(r) < node.line.get(r):
                if not node.right:
                    node.right = LiChaoNode(mid + 1, r)
                self.insert(node.right, new_line)
            else:
                if not node.left:
                    node.left = LiChaoNode(l, mid)
                self.insert(node.left, new_line)

    def query(self, node, x):
        if not node:
            return float('inf')
        res = node.line.get(x)
        mid = (node.l + node.r) // 2
        if x <= mid:
            left_res = self.query(node.left, x)
            return min(res, left_res)
        else:
            right_res = self.query(node.right, x)
            return min(res, right_res)

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    results = []
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        A = []
        B = []
        C = []
        for _ in range(N):
            a = int(input[ptr])
            b = int(input[ptr+1])
            c = int(input[ptr+2])
            A.append(a)
            B.append(b)
            C.append(c)
            ptr += 3
        # Check if any (C_i - B_i -1) is negative
        valid = True
        for i in range(N):
            if C[i] - B[i] - 1 < 0:
                valid = False
                break
        if not valid:
            results.append(0)
            continue
        # Compute X_max
        X_max = float('inf')
        for i in range(N):
            numerator = C[i] - B[i] - 1
            denominator = A[i]
            if denominator == 0:
                valid = False
                break
            x = numerator // denominator
            if x < 0:
                valid = False
                break
            if x < X_max:
                X_max = x
        if not valid or X_max < 1:
            results.append(0)
            continue
        # Now, build the lines
        lines = []
        for i in range(N):
            m = -A[i] / B[i]
            b = (C[i] - 1) / B[i]
            lines.append(Line(m, b))
        # Build the Li Chao tree
        tree = LiChaoTree(1, X_max)
        for line in lines:
            tree.insert(tree.root, line)
        # Query each x
        total = 0
        for x in range(1, X_max + 1):
            min_val = tree.query(tree.root, x)
            floor_val = math.floor(min_val)
            if floor_val >= 1:
                total += floor_val
        results.append(total)
    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
```

### Explanation
- **Li Chao Tree**: This data structure is used to maintain and query the minimum value of linear functions over a range of x values efficiently. It helps us determine the minimum value of the linear functions derived from the sequences A, B, and C for each valid x.
- **Range Calculation**: The valid range of x values is determined by checking if the condition $ A_i \times x < C_i - B_i $ holds for all i. This ensures that the inequality can be satisfied for some y.
- **Querying Valid y Values**: For each x in the valid range, we query the minimum value of the linear functions and use the floor of this value to determine the number of valid y values. This approach ensures we efficiently count all valid pairs (x, y) for each test case.

